            void mutate(importedData, { revalidate: false });
          }}
          onUnauthorized={handleUnauthorized}
        />

        <TrackingSettings onUnauthorized={handleUnauthorized} />

        <MailSettings onUnauthorized={handleUnauthorized} />

        {/* Admin 범례 (진행중 → 진행으로 수정) */}
        <div className="flex gap-6 text-sm mb-6 bg-white p-4 rounded-2xl shadow">
          <div className="flex items-center gap-2">
            <div className="w-4 h-4 rounded-full bg-blue-600"></div>
            <span>완료</span>
          </div>
          <div className="flex items-center gap-2">
            <Loader2 size={16} className="animate-spin text-orange-500" />
            <span>진행</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-4 h-4 rounded-full border-2 border-red-500 bg-transparent"></div>
            <span>지연</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-4 h-4 rounded-full bg-gray-400"></div>
            <span>대기</span>
          </div>
        </div>

        <div className="space-y-1 bg-white rounded-3xl shadow-sm p-2">
          {tree.map(node => (
            <ActivityTree 
              key={node.id} 
              node={node} 
              forceCollapsed={false}
              isAdmin={true}
              onStatusChange={async (id, newStatus) => {
                let activities = [...(data.activities || [])];

                // 대상과 모든 하위(parentId 관계)를 같은 상태로
                const affected = collectDescendantIds(activities, id);
                activities = activities.map((a: Activity) => {
                  if (affected.has(a.id)) {
                    return { ...a, status: newStatus };
                  }
                  return a;
                });

                // 부모 자동 진행 처리
                if (newStatus === '대기' || newStatus === '진행') {
                  const target = activities.find((a: Activity) => a.id === id);
                  if (target?.parentId) {
                    activities = activities.map((a: Activity) => {
                      if (a.id === target.parentId) {
                        return { ...a, status: '진행' };
                      }
                      return a;
                    });
                  }
                }

                // 자식 모두 완료 시 부모 완료
                if (newStatus === '완료') {
                  const target = activities.find((a: Activity) => a.id === id);
                  if (target?.parentId) {
                    const siblings = activities.filter((a: Activity) => a.parentId === target.parentId);
                    if (siblings.every((a: Activity) => a.status === '완료')) {
                      activities = activities.map((a: Activity) => {
                        if (a.id === target.parentId) {
                          return { ...a, status: '완료' };
                        }
                        return a;
                      });
                    }
                  }
                }

                await fetch('/api/activities', {
                  method: 'PUT',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ activities, targetId: id, newStatus })
                });

                mutate();
              }}
              onUpdateActivity={async (id, updated) => {
                const newActivities = data.activities.map((a: Activity) =>
                  a.id === id ? { ...a, ...updated } : a
                );
                await fetch('/api/activities', {
                  method: 'PUT',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ activities: newActivities, targetId: id })
                });
                mutate();
              }}
              onDeleteActivity={async (id) => {
                if (!confirm(`"${node.title}" 및 모든 하위 액티비티를 삭제하시겠습니까?`)) return;
                await fetch('/api/activities', {
                  method: 'PUT',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ action: 'delete', targetId: id })
                });
                mutate();
              }}
              onMoveActivity={async (id, direction) => {
                await fetch('/api/activities', {
                  method: 'PUT',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ action: 'move', targetId: id, direction })
                });
                mutate();
              }}
              onAddActivity={async (parentId) => {
                await fetch('/api/activities', {
                  method: 'PUT',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify({ action: 'add', parentId })
                });
                mutate();
              }}
            />
          ))}
        </div>
      </div>
    </div>
  );
}
'use client';
import { useEffect, useState } from 'react';
import { 
  ChevronDown, 
  ChevronRight, 
  Loader2, 
  Edit3, 
  Save, 
  X, 
  Trash2, 
  Plus, 
  ArrowUp, 
  ArrowDown 
} from 'lucide-react';
import { Activity } from '@/lib/types';

interface Props {
  node: Activity;
  onStatusChange?: (id: string, status: Activity['status']) => void;
  onUpdateActivity?: (id: string, updated: Partial<Activity>) => void;
  onDeleteActivity?: (id: string) => void;
  onMoveActivity?: (id: string, direction: 'up' | 'down') => void;
  onAddActivity?: (parentId: string | null) => void;
  forceCollapsed?: boolean;
  isAdmin?: boolean;
}

function StatusIcon({ status }: { status: Activity['status'] }) {
  switch (status) {
    case '진행':
      return <Loader2 size={18} className="animate-spin flex-shrink-0 text-orange-500" />;
    case '완료':
      return <div className="w-4 h-4 rounded-full flex-shrink-0 bg-blue-600" />;
    case '지연':
      return <div className="w-4 h-4 rounded-full flex-shrink-0 border-2 border-red-500 bg-transparent" />;
    default:
      return <div className="w-4 h-4 rounded-full flex-shrink-0 bg-gray-400" />;
  }
}

export default function ActivityTree({ 
  node, 
  onStatusChange, 
  onUpdateActivity, 
  onDeleteActivity, 
  onMoveActivity,
  onAddActivity,
  forceCollapsed = false,
  isAdmin = false 
}: Props) {
  const [expanded, setExpanded] = useState(true);
  const [isEditing, setIsEditing] = useState(false);
  const [editData, setEditData] = useState({ title: node.title, time: node.time });

  const hasChildren = node.children && node.children.length > 0;
  const isRoot = node.level === 1;

  useEffect(() => {
    // 전체 펼침/접힘 버튼은 각 노드에서 사용자가 선택한 상태보다 우선합니다.
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setExpanded(isAdmin || !forceCollapsed);
  }, [forceCollapsed, isAdmin]);

  const toggleExpand = () => {
    if (!isAdmin && hasChildren) {
      setExpanded(!expanded);
    }
  };

  const handleSave = () => {
    if (onUpdateActivity) onUpdateActivity(node.id, editData);
    setIsEditing(false);
  };

  return (
    <div className="mb-1">
      <div 
        className="border border-gray-200 bg-white rounded-2xl overflow-hidden cursor-pointer"
        onClick={toggleExpand}
      >
        <div className="flex items-center gap-3 py-2 px-3 hover:bg-gray-50 transition-all relative">
          {hasChildren && (
            <button onClick={(e) => { e.stopPropagation(); if (!isAdmin) setExpanded(!expanded); }} className="text-gray-500 hover:text-gray-900 flex-shrink-0">
              {expanded ? <ChevronDown size={18} /> : <ChevronRight size={18} />}
            </button>
          )}

          <StatusIcon status={node.status} />

          <div className="flex-1 min-w-0 pr-2">
            {isEditing ? (
              <div className="space-y-1">
                <input type="text" value={editData.time} onChange={e => setEditData({...editData, time: e.target.value})} className="w-full border border-gray-300 rounded px-2 py-0.5 text-xs" />
                <input type="text" value={editData.title} onChange={e => setEditData({...editData, title: e.target.value})} className="w-full border border-gray-300 rounded px-2 py-1 font-medium" />
              </div>
            ) : (
              <>
                <div className="text-xs text-gray-500 font-mono tracking-tight">{node.time}</div>
                <div className="font-semibold text-gray-900 text-[15px] leading-tight break-keep">{node.title}</div>
              </>
            )}
          </div>

          {isAdmin && (
            <div className="flex items-center gap-1" onClick={(e) => e.stopPropagation()}>
              <button onClick={() => onAddActivity?.(node.id)} className="text-blue-600 hover:text-blue-700 p-1" title="하위 추가">
                <Plus size={18} />
              </button>
              {isRoot && (
                <button onClick={() => onAddActivity?.(null)} className="text-blue-600 hover:text-blue-700 p-1" title="같은 레벨 추가">
                  <Plus size={18} />
                </button>
              )}

              <button onClick={() => onMoveActivity?.(node.id, 'up')} className="text-gray-400 hover:text-gray-700 p-1" title="위로 이동">
                <ArrowUp size={18} />
              </button>
              <button onClick={() => onMoveActivity?.(node.id, 'down')} className="text-gray-400 hover:text-gray-700 p-1" title="아래로 이동">
                <ArrowDown size={18} />
              </button>

              <button onClick={() => confirm(`"${node.title}" 및 모든 하위 액티비티를 삭제하시겠습니까?`) && onDeleteActivity?.(node.id)} className="text-red-600 hover:text-red-700 p-1">
                <Trash2 size={18} />
              </button>

              {isEditing ? (
                <>
                  <button onClick={handleSave} className="text-emerald-600 p-1"><Save size={18} /></button>
                  <button onClick={() => {setIsEditing(false); setEditData({title: node.title, time: node.time});}} className="text-gray-500 p-1"><X size={18} /></button>
                </>
              ) : (
                <button 
                  onClick={(e) => { e.stopPropagation(); setIsEditing(true); }} 
                  className="text-gray-500 p-1"
                >
                  <Edit3 size={18} />
                </button>
              )}

              <select 
                value={node.status} 
                onChange={(e) => onStatusChange?.(node.id, e.target.value as Activity['status'])} 
                onClick={(e) => e.stopPropagation()} 
                className="bg-white border border-gray-300 rounded-xl text-sm px-3 py-1.5 text-gray-900 ml-1 cursor-pointer"
              >
                <option value="대기">대기</option>
                <option value="진행">진행</option>
                <option value="지연">지연</option>
                <option value="완료">완료</option>
              </select>
            </div>
          )}
        </div>

        {expanded && hasChildren && (
          <div className="pl-8 pr-3 pb-2 border-t border-gray-100">
            {node.children!.map((child: Activity) => (
              <ActivityTree 
                key={child.id} 
                node={child} 
                onStatusChange={onStatusChange}
                onUpdateActivity={onUpdateActivity}
                onDeleteActivity={onDeleteActivity}
                onMoveActivity={onMoveActivity}
                onAddActivity={onAddActivity}
                forceCollapsed={forceCollapsed}
                isAdmin={isAdmin} 
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
import type { Activity } from './types.ts';

export function buildTree(activities: Activity[]): Activity[] {
  const map = new Map<string, Activity>();
  const roots: Activity[] = [];

  activities.forEach(act => {
    map.set(act.id, { ...act, children: [] });
  });

  activities.forEach(act => {
    const node = map.get(act.id)!;
    if (act.parentId) {
      const parent = map.get(act.parentId);
      if (parent) parent.children!.push(node);
    } else {
      roots.push(node);
    }
  });

  return roots;
}

export function moveActivity(activities: Activity[], targetId: string, direction: 'up' | 'down'): Activity[] {
  const newActivities = [...activities];
  const targetIndex = newActivities.findIndex(a => a.id === targetId);
  if (targetIndex === -1) return newActivities;

  const target = newActivities[targetIndex];
  const siblings = newActivities.filter(a => a.parentId === target.parentId);
  const siblingIds = siblings.map(s => s.id);
  const currentIndex = siblingIds.indexOf(targetId);

  if (direction === 'up' && currentIndex > 0) {
    const prevId = siblingIds[currentIndex - 1];
    const prevIndex = newActivities.findIndex(a => a.id === prevId);
    [newActivities[targetIndex], newActivities[prevIndex]] = [newActivities[prevIndex], newActivities[targetIndex]];
  } else if (direction === 'down' && currentIndex < siblingIds.length - 1) {
    const nextId = siblingIds[currentIndex + 1];
    const nextIndex = newActivities.findIndex(a => a.id === nextId);
    [newActivities[targetIndex], newActivities[nextIndex]] = [newActivities[nextIndex], newActivities[targetIndex]];
  }

  return newActivities;
}

export function addActivity(activities: Activity[], parentId: string | null): Activity[] {
  const newActivities = [...activities];
  const newId = parentId ? `${parentId}-${Date.now()}` : `${Date.now()}`;

  const newActivity: Activity = {
    id: newId,
    parentId: parentId || null,
    level: parentId ? (newActivities.find(a => a.id === parentId)?.level || 0) + 1 : 1,
    time: "미정",
    title: "새 액티비티",
    status: "대기"
  };

  newActivities.push(newActivity);
  return newActivities;
}

/**
 * rootId 와 그 아래 모든 하위(parentId 관계)의 id 를 모은다.
 * id 는 업로드한 activity.json 에서 아무 문자열이나 될 수 있으므로 `부모-번호` 접두사에 기대지 않는다.
 * parentId 가 순환하는 데이터가 들어와도 visited 로 끝난다.
 */
export function collectDescendantIds(activities: Activity[], rootId: string): Set<string> {
  const childrenByParent = new Map<string, string[]>();
  activities.forEach(act => {
    if (act.parentId === null || act.parentId === undefined) return;
    const siblings = childrenByParent.get(act.parentId);
    if (siblings) siblings.push(act.id);
    else childrenByParent.set(act.parentId, [act.id]);
  });

  const visited = new Set<string>([rootId]);
  const queue = [rootId];
  while (queue.length > 0) {
    const current = queue.shift()!;
    for (const childId of childrenByParent.get(current) ?? []) {
      if (visited.has(childId)) continue;
      visited.add(childId);
      queue.push(childId);
    }
  }
  return visited;
}

export function deleteActivity(activities: Activity[], targetId: string): Activity[] {
  const removed = collectDescendantIds(activities, targetId);
  return activities.filter(a => !removed.has(a.id));
}

